SELECT COUNT(*) AS long_film_count
FROM film
WHERE length > (SELECT AVG(length) FROM film);

SELECT COUNT(*) AS rentals_in_2025_utc
FROM rental
WHERE rental_date >= '2025-01-01 00:00:00' AND rental_date < '2026-01-01 00:00:00';

SELECT ROUND(AVG(day_diff), 2) AS avg_days_between_consecutive_rentals
FROM (
  SELECT TIMESTAMPDIFF(DAY, LAG(rental_date) OVER (PARTITION BY customer_id ORDER BY rental_date), rental_date) AS day_diff
  FROM rental
) AS t
WHERE day_diff IS NOT NULL;

SELECT ROUND(AVG(day_diff), 2) AS average_days_between_consecutive_rentals
FROM (
  SELECT customer_id, (EXTRACT(EPOCH FROM (rental_date - prev_rental_date)) / 86400.0) AS day_diff
  FROM (
    SELECT rental_date, customer_id, LAG(rental_date) OVER (PARTITION BY customer_id ORDER BY rental_date) AS prev_rental_date
    FROM rental
  ) sub
  WHERE prev_rental_date IS NOT NULL
) t;
